// Normalize raw teacher input into a consistent shape.
// Does NOT change the meaning of any value - only trims/casts types.
// Source may be a classic webhook body (nested under .body) or an n8n Form
// Trigger submission (fields directly on json, keyed by fieldName - or, on
// older n8n versions where fieldName isn't honored, keyed by the fieldLabel
// text). pick() checks both possible keys so this stays compatible either way.
const body = $input.first().json.body || $input.first().json;

function pick(technicalName, labelName) {
  if (body[technicalName] !== undefined) return body[technicalName];
  if (labelName !== undefined && body[labelName] !== undefined) return body[labelName];
  return undefined;
}

function toInt(v) {
  if (v === undefined || v === null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? Math.trunc(n) : null;
}
function toStr(v) {
  return (v === undefined || v === null) ? '' : String(v).trim();
}

const normalized = {
  class: toStr(pick('class', 'Class')),
  section: toStr(pick('section', 'Section')),
  subject: toStr(pick('subject', 'Subject')),
  examType: toStr(pick('examType', 'Exam Type')),
  maximumMarks: toInt(pick('maximumMarks', 'Maximum Marks')),
  time: toStr(pick('time', 'Exam Time')),
  totalQuestions: toInt(pick('totalQuestions', 'Total Questions')),
  questionsToAnswer: toInt(pick('questionsToAnswer', 'Questions to Answer')),
  marksPerQuestion: toInt(pick('marksPerQuestion', 'Marks per Question')),
  numberOfSets: toInt(pick('numberOfSets', 'Number of Sets')),
  academicYear: toStr(pick('academicYear', 'Academic Year')) || '2026-27'
};

return [{ json: { input: normalized } }];

const input = $input.first().json.input;
const errors = [];

function required(field, label) {
  const v = input[field];
  if (v === null || v === undefined || v === '') {
    errors.push(`${label} is required`);
  }
}

required('class', 'Class');
required('section', 'Section');
required('subject', 'Subject');
required('examType', 'Exam Type');
required('time', 'Time');

if (input.maximumMarks === null) errors.push('Maximum Marks is required');
if (input.totalQuestions === null) errors.push('Total Questions is required');
if (input.questionsToAnswer === null) errors.push('Questions to Answer is required');
if (input.marksPerQuestion === null) errors.push('Marks per Question is required');
if (input.numberOfSets === null) errors.push('Number of Sets is required');

return [{
  json: {
    input,
    validation: {
      stage: 'required_fields',
      valid: errors.length === 0,
      errors
    }
  }
}];

const input = $input.first().json.input;
const errors = [];

if (!(Number.isInteger(input.maximumMarks) && input.maximumMarks > 0)) {
  errors.push('Maximum Marks must be a number greater than zero');
}
if (!(Number.isInteger(input.totalQuestions) && input.totalQuestions > 0)) {
  errors.push('Total Questions must be a positive integer');
}
if (!(Number.isInteger(input.questionsToAnswer) && input.questionsToAnswer > 0)) {
  errors.push('Questions to Answer must be a positive integer');
}
if (Number.isInteger(input.totalQuestions) && Number.isInteger(input.questionsToAnswer)
    && input.questionsToAnswer > input.totalQuestions) {
  errors.push('Questions to Answer must not exceed Total Questions');
}
if (!(Number.isInteger(input.marksPerQuestion) && input.marksPerQuestion > 0)) {
  errors.push('Marks per Question must be greater than zero');
}
if (![1, 2].includes(input.numberOfSets)) {
  errors.push('Number of Sets must be exactly 1 or 2');
}

// Cross-field check: Questions to Answer x Marks per Question = Maximum Marks
if (Number.isInteger(input.questionsToAnswer) && Number.isInteger(input.marksPerQuestion)
    && Number.isInteger(input.maximumMarks)) {
  const computed = input.questionsToAnswer * input.marksPerQuestion;
  if (computed !== input.maximumMarks) {
    errors.push(
      `Questions to Answer (${input.questionsToAnswer}) x Marks per Question (${input.marksPerQuestion}) ` +
      `= ${computed}, which does not equal Maximum Marks (${input.maximumMarks})`
    );
  }
}

return [{
  json: {
    input,
    validation: {
      stage: 'marks_rules',
      valid: errors.length === 0,
      errors
    }
  }
}];

const input = $input.first().json.input;

const lookupKey = {
  classKey: String(input.class).trim(),
  subjectKey: String(input.subject).trim().toLowerCase(),
  academicYear: input.academicYear
};

return [{ json: { input, lookupKey } }];

// -----------------------------------------------------------------
// CURRICULUM SOURCE (DEMO)
// -----------------------------------------------------------------
// This node is intentionally isolated so it can later be replaced
// with a real data source (Google Sheets, database, or school API)
// WITHOUT touching any other node in this workflow.
//
// Contract this node must always fulfil:
//   INPUT:  { class, subject, academicYear }
//   OUTPUT: { curriculum: { class, subject, academicYear, chapters: [...] } }
//
// To swap the source later:
//   - Replace the body of this Code node with an HTTP Request / Google
//     Sheets / Database node that returns the same "curriculum" shape.
// -----------------------------------------------------------------

const input = $input.first().json.input;
const lookupKey = $input.first().json.lookupKey;

const CURRICULUM_DB = {
  '8|mathematics|2026-27': {
    class: '8',
    subject: 'Mathematics',
    academicYear: '2026-27',
    chapters: [
      {
        chapter: 'Rational Numbers',
        topics: [
          'Properties of rational numbers',
          'Operations on rational numbers'
        ]
      },
      {
        chapter: 'Linear Equations',
        topics: [
          'Solving linear equations',
          'Applications of linear equations'
        ]
      }
    ]
  }
};

const key = `${lookupKey.classKey}|${lookupKey.subjectKey}|${lookupKey.academicYear}`;
const curriculum = CURRICULUM_DB[key];

if (!curriculum) {
  return [{
    json: {
      input,
      curriculumError: `No curriculum found for Class ${input.class}, ` +
        `Subject ${input.subject}, Academic Year ${input.academicYear}`
    }
  }];
}

return [{ json: { input, curriculum } }];

const input = $input.first().json.input;
const curriculum = $input.first().json.curriculum;

const examConfig = {
  class: input.class,
  section: input.section,
  subject: input.subject,
  examType: input.examType,
  maximumMarks: input.maximumMarks,
  time: input.time,
  totalQuestions: input.totalQuestions,
  questionsToAnswer: input.questionsToAnswer,
  marksPerQuestion: input.marksPerQuestion,
  numberOfSets: input.numberOfSets,
  academicYear: input.academicYear,
  curriculum
};

return [{ json: { examConfig } }];

const result = $input.first().json;
const ok = result && result.success === true
  && Array.isArray(result.sets) && result.sets.length > 0;

return [{
  json: {
    questionPaperData: result,
    wf2Validation: {
      valid: ok,
      errors: ok ? [] : ['Workflow 2 did not return a valid structured question-paper result']
    }
  }
}];

const questionPaperData = $input.first().json.questionPaperData;

// Workflow 3 receives exactly the validated question-paper JSON produced by
// Workflow 2 - Workflow 1 does not alter academic content, only forwards it.
return [{ json: { documentInput: questionPaperData } }];

const result = $input.first().json;
const ok = result && result.success === true
  && Array.isArray(result.documents) && result.documents.length > 0;

return [{
  json: {
    documentResult: result,
    wf3Validation: {
      valid: ok,
      errors: ok ? [] : ['Workflow 3 did not return valid document information']
    }
  }
}];

const documentResult = $json.documentResult;

return [{
  json: {
    success: true,
    exam: documentResult.exam,
    documents: documentResult.documents
  }
}];

// Builds the completion-page content for the Form Ending node from the
// validated success payload (Build Final Success Response) plus the exam
// details already captured earlier in this same execution. This node only
// formats display text/links - it does not touch question-paper/document
// generation logic, which lives entirely in Workflow 02 and Workflow 03.
const successPayload = $input.first().json; // { success, exam, documents }
const examConfig = $('Prepare Exam Configuration').first().json.examConfig;

const documents = Array.isArray(successPayload.documents) ? successPayload.documents : [];

// Workflow 3 (03_DOCUMENT_GENERATOR) is unchanged by this update, so the
// exact shape of each "documents" entry isn't assumed here - the filename
// and set label are read from whichever of these common keys is present.
// A local filesystem path (e.g. /data/question-papers/Question_Paper_Set_A.pdf)
// is reduced to just its filename, since only the filename is passed to the
// PDF_DOWNLOAD workflow's download endpoint.
function extractFilename(doc) {
  const raw = (doc && (doc.filename || doc.fileName || doc.file || doc.path || doc.filePath)) || '';
  const segments = String(raw).split(/[\\/]/);
  return segments[segments.length - 1] || '';
}
function extractSetLabel(doc, index) {
  const raw = doc && (doc.setName || doc.set || doc.name || doc.label);
  if (raw) return String(raw);
  return index === 0 ? 'Set A' : 'Set B';
}
function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// N8N_PUBLIC_URL must be set as an n8n environment variable pointing at this
// instance's public base URL (e.g. https://your-instance.app.n8n.cloud).
// The placeholder below is only used if that variable hasn't been configured.
const N8N_PUBLIC_URL = $env.N8N_PUBLIC_URL || 'https://YOUR_N8N_PUBLIC_URL';

const links = documents.map((doc, index) => {
  const filename = extractFilename(doc);
  const setLabel = extractSetLabel(doc, index);
  const url = `${N8N_PUBLIC_URL}/webhook/question-paper-download?file=${encodeURIComponent(filename)}`;
  return { setLabel, filename, url };
});

const linksHtml = links
  .map(l => `<p><a href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer">Download ${escapeHtml(l.setLabel)} PDF</a></p>`)
  .join('\n');

const completionMessage =
  `<p><strong>Class:</strong> ${escapeHtml(examConfig.class)} &nbsp;&nbsp; ` +
  `<strong>Subject:</strong> ${escapeHtml(examConfig.subject)} &nbsp;&nbsp; ` +
  `<strong>Exam Type:</strong> ${escapeHtml(examConfig.examType)}</p>` +
  `<p><strong>Sets generated:</strong> ${escapeHtml(examConfig.numberOfSets)}</p>` +
  linksHtml;

return [{
  json: {
    completionTitle: 'Question Paper Generated Successfully',
    completionMessage
  }
}];

// Collects errors from whichever validation stage failed and returns
// a single consistent error envelope.
const j = $input.first().json;

let code = 'UNKNOWN_ERROR';
let errors = [];

if (j.validation && j.validation.stage === 'required_fields') {
  code = 'INVALID_INPUT';
  errors = j.validation.errors;
} else if (j.validation && j.validation.stage === 'marks_rules') {
  code = 'INVALID_MARKS_CONFIGURATION';
  errors = j.validation.errors;
} else if (j.curriculumError) {
  code = 'CURRICULUM_NOT_FOUND';
  errors = [j.curriculumError];
} else if (j.wf2Validation) {
  code = 'QUESTION_ENGINE_FAILED';
  errors = j.wf2Validation.errors;
} else if (j.wf3Validation) {
  code = 'DOCUMENT_GENERATION_FAILED';
  errors = j.wf3Validation.errors;
} else {
  errors = ['An unexpected error occurred in 01_EXAM_CONTROLLER'];
}

return [{
  json: {
    success: false,
    error: {
      code,
      message: errors.join('; ')
    }
  }
}];

// Turns the existing curated error envelope from Format Error Response into
// readable Form Ending content. Format Error Response already strips this
// down to a { code, message } pair with no internal paths, credentials, or
// stack traces - this node only wraps that message for display and does not
// change what is exposed.
const err = $input.first().json; // { success: false, error: { code, message } }
const message = (err && err.error && err.error.message)
  ? err.error.message
  : 'An unexpected error occurred.';

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

return [{
  json: {
    completionTitle: 'Question Paper Could Not Be Generated',
    completionMessage: `<p>Question paper could not be generated.</p><p>${escapeHtml(message)}</p>`
  }
}];
